-- Additive migration: the week-1 public schema and its data stay intact.
CREATE SCHEMA IF NOT EXISTS campus;
SET LOCAL search_path = campus, public;
CREATE TABLE schema_migrations(version text PRIMARY KEY, checksum text NOT NULL, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users(id uuid PRIMARY KEY, email text UNIQUE NOT NULL, name text NOT NULL, password_hash text NOT NULL, status text NOT NULL DEFAULT 'ACTIVE' CHECK(status IN('ACTIVE','LOCKED','DISABLED')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE roles(code text PRIMARY KEY CHECK(code IN('ADMIN','STUDENT','LECTURER','PARKING_STAFF','CANTEEN_STAFF')));
CREATE TABLE permissions(code text PRIMARY KEY);
CREATE TABLE user_roles(user_id uuid REFERENCES users, role text REFERENCES roles, PRIMARY KEY(user_id,role));
CREATE TABLE role_permissions(role text REFERENCES roles, permission text REFERENCES permissions, PRIMARY KEY(role,permission));
CREATE TABLE students(id uuid PRIMARY KEY, user_id uuid UNIQUE NOT NULL REFERENCES users, student_code text UNIQUE NOT NULL, synthetic boolean NOT NULL DEFAULT false, active boolean NOT NULL DEFAULT true);
CREATE TABLE lecturers(id uuid PRIMARY KEY, user_id uuid UNIQUE NOT NULL REFERENCES users, lecturer_code text UNIQUE NOT NULL);
CREATE TABLE auth_sessions(id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users, access_hash text UNIQUE NOT NULL, refresh_hash text UNIQUE NOT NULL, family_id uuid NOT NULL, access_expires_at timestamptz NOT NULL, refresh_expires_at timestamptz NOT NULL, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE auth_sessions ADD COLUMN authenticated_at timestamptz NOT NULL DEFAULT now();
CREATE INDEX session_family ON auth_sessions(family_id);
CREATE TABLE wallet_security_settings(student_id uuid PRIMARY KEY REFERENCES students, pin_hash text NOT NULL, pin_version integer NOT NULL DEFAULT 1, failed_count integer NOT NULL DEFAULT 0, locked_until timestamptz);
CREATE TABLE rfid_cards(id uuid PRIMARY KEY, student_id uuid NOT NULL REFERENCES students, uid_hmac text NOT NULL, status text NOT NULL CHECK(status IN('ACTIVE','LOST','REVOKED','EXPIRED')), expires_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), revoked_at timestamptz);
CREATE UNIQUE INDEX active_card_student ON rfid_cards(student_id) WHERE status='ACTIVE';
CREATE UNIQUE INDEX active_card_uid ON rfid_cards(uid_hmac) WHERE status='ACTIVE';
CREATE TABLE biometric_consents(id uuid PRIMARY KEY, student_id uuid NOT NULL REFERENCES students, purpose text NOT NULL CHECK(purpose IN('ATTENDANCE','PARKING','CANTEEN')), policy_version text NOT NULL, source text NOT NULL CHECK(source IN('DEMO','REAL')), granted_at timestamptz NOT NULL DEFAULT now(), revoked_at timestamptz);
CREATE TABLE biometric_profiles(id uuid PRIMARY KEY, student_id uuid NOT NULL REFERENCES students, consent_id uuid NOT NULL REFERENCES biometric_consents, purpose text NOT NULL, source text NOT NULL CHECK(source IN('DEMO','REAL')), model_version text NOT NULL, status text NOT NULL CHECK(status IN('ACTIVE','REVOKED','ERASED')), erased_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX one_active_biometric_profile ON biometric_profiles(student_id,purpose) WHERE status='ACTIVE';
CREATE TABLE parking_lots(id uuid PRIMARY KEY, code text UNIQUE NOT NULL, name text NOT NULL, capacity integer NOT NULL CHECK(capacity>0));
CREATE TABLE classrooms(id uuid PRIMARY KEY, code text UNIQUE NOT NULL, name text NOT NULL);
CREATE TABLE devices(id uuid PRIMARY KEY, name text NOT NULL, kind text NOT NULL CHECK(kind IN('RFID_READER','ATTENDANCE_CAMERA','DEMO_TERMINAL')), token_hash text UNIQUE, active boolean NOT NULL DEFAULT true, role text NOT NULL CHECK(role IN('PARKING_ENTRY','PARKING_EXIT','CANTEEN_POS','RFID_ENROLLMENT','ATTENDANCE_CAMERA')), config_version integer NOT NULL DEFAULT 1, ack_version integer NOT NULL DEFAULT 0, parking_lot_id uuid REFERENCES parking_lots, classroom_id uuid REFERENCES classrooms, last_seen_at timestamptz, last_uid_mask text);
CREATE TABLE device_role_bindings(id uuid PRIMARY KEY, device_id uuid NOT NULL REFERENCES devices, role text NOT NULL, config_version integer NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), released_at timestamptz);
CREATE UNIQUE INDEX one_device_binding ON device_role_bindings(device_id) WHERE released_at IS NULL;
CREATE TABLE vehicles(id uuid PRIMARY KEY, normalized_plate text UNIQUE NOT NULL, raw_plate text NOT NULL, vehicle_type text NOT NULL, active boolean NOT NULL DEFAULT true);
CREATE TABLE vehicle_authorizations(vehicle_id uuid REFERENCES vehicles, student_id uuid REFERENCES students, valid_from timestamptz NOT NULL DEFAULT now(), valid_to timestamptz, active boolean NOT NULL DEFAULT true, PRIMARY KEY(vehicle_id,student_id), CHECK(valid_to IS NULL OR valid_to>valid_from));
CREATE TABLE parking_fee_policies(id uuid PRIMARY KEY, lot_id uuid NOT NULL REFERENCES parking_lots, version text NOT NULL, mode text NOT NULL CHECK(mode IN('PER_VISIT','PER_HOUR','PER_DAY')), unit_points bigint NOT NULL CHECK(unit_points>=0), grace_minutes integer NOT NULL DEFAULT 0 CHECK(grace_minutes>=0), daily_cap bigint CHECK(daily_cap>0), active boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(lot_id,version));
CREATE UNIQUE INDEX one_active_policy ON parking_fee_policies(lot_id) WHERE active;
CREATE TABLE parking_passes(id uuid PRIMARY KEY, student_id uuid NOT NULL REFERENCES students, vehicle_id uuid NOT NULL REFERENCES vehicles, lot_id uuid NOT NULL REFERENCES parking_lots, valid_from timestamptz NOT NULL, valid_to timestamptz NOT NULL, reason text NOT NULL, CHECK(valid_to>valid_from));
ALTER TABLE parking_passes ADD COLUMN discount_bps integer NOT NULL DEFAULT 10000 CHECK(discount_bps BETWEEN 0 AND 10000);
CREATE TABLE parking_sessions(id uuid PRIMARY KEY, student_id uuid NOT NULL REFERENCES students, vehicle_id uuid NOT NULL REFERENCES vehicles, lot_id uuid NOT NULL REFERENCES parking_lots, policy_id uuid NOT NULL REFERENCES parking_fee_policies, status text NOT NULL CHECK(status IN('PENDING_ENTRY','ACTIVE','EXIT_PENDING','COMPLETED','CANCELLED','EXCEPTION')), settlement_cycle integer NOT NULL DEFAULT 1, entry_plate text NOT NULL, exit_plate text, entry_source text NOT NULL CHECK(entry_source IN('REAL','DEMO')), entered_at timestamptz, exited_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1, UNIQUE(id,student_id), CHECK(exited_at IS NULL OR exited_at>=entered_at));
CREATE UNIQUE INDEX one_unsettled_vehicle ON parking_sessions(vehicle_id) WHERE status IN('PENDING_ENTRY','ACTIVE','EXIT_PENDING','EXCEPTION');
CREATE TABLE parking_occupancies(vehicle_id uuid PRIMARY KEY REFERENCES vehicles, session_id uuid UNIQUE NOT NULL REFERENCES parking_sessions, lot_id uuid NOT NULL REFERENCES parking_lots);
CREATE TABLE parking_quotes(id uuid PRIMARY KEY, session_id uuid NOT NULL REFERENCES parking_sessions, settlement_cycle integer NOT NULL, amount_points bigint NOT NULL CHECK(amount_points>=0), fee_snapshot jsonb NOT NULL, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE product_categories(id uuid PRIMARY KEY, name text UNIQUE NOT NULL);
CREATE TABLE products(id uuid PRIMARY KEY, category_id uuid NOT NULL REFERENCES product_categories, sku text UNIQUE NOT NULL, name text NOT NULL, price_points bigint NOT NULL CHECK(price_points>0), price_version integer NOT NULL DEFAULT 1, active boolean NOT NULL DEFAULT true, image_ref text);
CREATE TABLE inventory(product_id uuid PRIMARY KEY REFERENCES products, on_hand integer NOT NULL DEFAULT 0, reserved integer NOT NULL DEFAULT 0, CHECK(on_hand>=reserved AND reserved>=0));
CREATE TABLE orders(id uuid PRIMARY KEY, created_by uuid NOT NULL REFERENCES users, student_id uuid REFERENCES students, status text NOT NULL CHECK(status IN('DRAFT','AWAITING_PAYMENT','COMPLETED','CANCELLED','EXPIRED')), total_points bigint NOT NULL CHECK(total_points>0), version integer NOT NULL DEFAULT 1, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz, UNIQUE(id,student_id));
CREATE TABLE order_items(id uuid PRIMARY KEY, order_id uuid NOT NULL REFERENCES orders, product_id uuid NOT NULL REFERENCES products, quantity integer NOT NULL CHECK(quantity>0), unit_price_points bigint NOT NULL CHECK(unit_price_points>0), price_version integer NOT NULL, UNIQUE(order_id,product_id));
CREATE TABLE inventory_reservations(order_id uuid REFERENCES orders, product_id uuid REFERENCES products, quantity integer NOT NULL CHECK(quantity>0), status text NOT NULL CHECK(status IN('ACTIVE','CONSUMED','RELEASED')), expires_at timestamptz NOT NULL, PRIMARY KEY(order_id,product_id));
CREATE TABLE ledger_accounts(id uuid PRIMARY KEY, kind text NOT NULL CHECK(kind IN('STUDENT','MOCK_SOURCE','CANTEEN','PARKING','ADJUSTMENT')), balance_points bigint NOT NULL DEFAULT 0, CHECK(kind IN('MOCK_SOURCE','ADJUSTMENT') OR balance_points>=0));
CREATE UNIQUE INDEX one_system_account ON ledger_accounts(kind) WHERE kind<>'STUDENT';
CREATE TABLE wallets(id uuid PRIMARY KEY, student_id uuid UNIQUE NOT NULL REFERENCES students, account_id uuid UNIQUE NOT NULL REFERENCES ledger_accounts, status text NOT NULL DEFAULT 'ACTIVE' CHECK(status IN('ACTIVE','FROZEN')));
CREATE TABLE payments(id uuid PRIMARY KEY, student_id uuid NOT NULL REFERENCES students, order_id uuid REFERENCES orders, parking_session_id uuid REFERENCES parking_sessions, quote_id uuid REFERENCES parking_quotes, settlement_cycle integer NOT NULL DEFAULT 1, amount_points bigint NOT NULL CHECK(amount_points>0), status text NOT NULL CHECK(status IN('AWAITING_CONFIRMATION','AUTHORIZED','CAPTURED','VOIDED','CANCELLED','EXPIRED')), created_at timestamptz NOT NULL DEFAULT now(), CHECK(num_nonnulls(order_id,parking_session_id)=1));
CREATE UNIQUE INDEX captured_order ON payments(order_id) WHERE status='CAPTURED';
CREATE UNIQUE INDEX captured_parking ON payments(parking_session_id,settlement_cycle) WHERE status='CAPTURED';
CREATE UNIQUE INDEX pending_order ON payments(order_id) WHERE status IN('AWAITING_CONFIRMATION','AUTHORIZED');
CREATE UNIQUE INDEX pending_parking ON payments(parking_session_id,settlement_cycle) WHERE status IN('AWAITING_CONFIRMATION','AUTHORIZED');
CREATE TABLE payment_approvals(id uuid PRIMARY KEY, payment_id uuid UNIQUE NOT NULL REFERENCES payments, student_id uuid NOT NULL REFERENCES students, amount_points bigint NOT NULL, source_version integer NOT NULL, pin_version integer NOT NULL, expires_at timestamptz NOT NULL, consumed_at timestamptz);
CREATE TABLE wallet_holds(id uuid PRIMARY KEY, wallet_id uuid NOT NULL REFERENCES wallets, payment_id uuid UNIQUE NOT NULL REFERENCES payments, amount_points bigint NOT NULL CHECK(amount_points>0), status text NOT NULL CHECK(status IN('ACTIVE','CAPTURED','RELEASED')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE point_conversion_policies(version text PRIMARY KEY, points_per_vnd integer NOT NULL CHECK(points_per_vnd>0), active boolean NOT NULL DEFAULT false);
CREATE UNIQUE INDEX active_conversion ON point_conversion_policies(active) WHERE active;
CREATE TABLE topup_orders(id uuid PRIMARY KEY, wallet_id uuid NOT NULL REFERENCES wallets, requested_vnd bigint NOT NULL CHECK(requested_vnd>0), amount_points bigint NOT NULL CHECK(amount_points>0), conversion_version text NOT NULL REFERENCES point_conversion_policies, status text NOT NULL CHECK(status IN('PENDING','SUCCEEDED','FAILED','CANCELLED','EXPIRED','REVIEW_REQUIRED')), provider text NOT NULL CHECK(provider='MOCK'), expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE payment_callbacks(id uuid PRIMARY KEY, provider_event_id text UNIQUE NOT NULL, topup_order_id uuid NOT NULL REFERENCES topup_orders, payload_hash text NOT NULL, processing_result text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE wallet_adjustments(id uuid PRIMARY KEY, student_id uuid NOT NULL REFERENCES students, delta_points bigint NOT NULL CHECK(delta_points<>0), reason text NOT NULL, actor_id uuid NOT NULL REFERENCES users, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE wallet_transactions(id uuid PRIMARY KEY, type text NOT NULL CHECK(type IN('TOP_UP','CANTEEN_PAYMENT','PARKING_PAYMENT','REFUND','REVERSAL','ADMIN_ADJUSTMENT')), student_id uuid NOT NULL REFERENCES students, amount_points bigint NOT NULL CHECK(amount_points>0), payment_id uuid UNIQUE REFERENCES payments, topup_order_id uuid UNIQUE REFERENCES topup_orders, original_transaction_id uuid REFERENCES wallet_transactions, refund_id uuid UNIQUE, adjustment_id uuid UNIQUE REFERENCES wallet_adjustments, created_at timestamptz NOT NULL DEFAULT now(), creation_xid xid8 NOT NULL DEFAULT pg_current_xact_id(), CHECK(num_nonnulls(payment_id,topup_order_id,refund_id,adjustment_id)=1));
CREATE TABLE refunds(id uuid PRIMARY KEY, original_transaction_id uuid NOT NULL REFERENCES wallet_transactions, amount_points bigint NOT NULL CHECK(amount_points>0), reason text NOT NULL, actor_id uuid NOT NULL REFERENCES users, restock boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE wallet_transactions ADD FOREIGN KEY(refund_id) REFERENCES refunds;
CREATE TABLE refund_items(refund_id uuid REFERENCES refunds, order_item_id uuid REFERENCES order_items, quantity integer NOT NULL CHECK(quantity>0), PRIMARY KEY(refund_id,order_item_id));
CREATE TABLE wallet_ledger_entries(id uuid PRIMARY KEY, transaction_id uuid NOT NULL REFERENCES wallet_transactions, account_id uuid NOT NULL REFERENCES ledger_accounts, delta_points bigint NOT NULL CHECK(delta_points<>0), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(transaction_id,account_id));
CREATE INDEX ledger_account_history ON wallet_ledger_entries(account_id,created_at,id);
CREATE TABLE wallet_daily_usage(wallet_id uuid REFERENCES wallets, business_date date, charged_points bigint NOT NULL CHECK(charged_points>=0), PRIMARY KEY(wallet_id,business_date));
CREATE TABLE parking_payments(payment_id uuid PRIMARY KEY REFERENCES payments, session_id uuid NOT NULL REFERENCES parking_sessions, quote_id uuid NOT NULL REFERENCES parking_quotes);
CREATE TABLE inventory_movements(id uuid PRIMARY KEY, product_id uuid NOT NULL REFERENCES products, order_id uuid REFERENCES orders, refund_id uuid REFERENCES refunds, kind text NOT NULL CHECK(kind IN('RECEIVE','RESERVE','RELEASE','SALE','RETURN','ADJUST')), quantity_delta integer NOT NULL, reason text, created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX stock_movement_order_once ON inventory_movements(product_id,order_id,kind) WHERE order_id IS NOT NULL;
CREATE UNIQUE INDEX stock_movement_refund_once ON inventory_movements(product_id,refund_id,kind) WHERE refund_id IS NOT NULL;
CREATE TABLE gate_commands(id uuid PRIMARY KEY, session_id uuid NOT NULL REFERENCES parking_sessions, device_id uuid NOT NULL REFERENCES devices, phase text NOT NULL CHECK(phase IN('ENTRY','EXIT')), settlement_cycle integer NOT NULL, status text NOT NULL CHECK(status IN('QUEUED','DISPATCHED','OPENED','PASSAGE_CONFIRMED','FAILED','UNKNOWN','REVOKED')), expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX one_live_gate ON gate_commands(session_id,phase) WHERE status IN('QUEUED','DISPATCHED','OPENED','UNKNOWN');
CREATE TABLE gate_provider_events(id uuid PRIMARY KEY, command_id uuid NOT NULL REFERENCES gate_commands, provider_event_id text UNIQUE NOT NULL, type text NOT NULL, source text NOT NULL CHECK(source='SIMULATOR'), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ocr_observations(id uuid PRIMARY KEY, context_id uuid, raw_text text, normalized_plate text, confidence numeric CHECK(confidence BETWEEN 0 AND 1), source text NOT NULL CHECK(source='DEMO'), status text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ocr_corrections(id uuid PRIMARY KEY, observation_id uuid NOT NULL REFERENCES ocr_observations, corrected_plate text NOT NULL, reason text NOT NULL, actor_id uuid NOT NULL REFERENCES users, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE parking_events(id uuid PRIMARY KEY, session_id uuid NOT NULL REFERENCES parking_sessions, type text NOT NULL, actor_id uuid REFERENCES users, source text NOT NULL, evidence_ref uuid REFERENCES ocr_observations, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE academic_terms(id uuid PRIMARY KEY, code text UNIQUE NOT NULL, starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL CHECK(ends_at>starts_at));
CREATE TABLE courses(id uuid PRIMARY KEY, code text UNIQUE NOT NULL, name text NOT NULL);
CREATE TABLE class_sections(id uuid PRIMARY KEY, term_id uuid NOT NULL REFERENCES academic_terms, course_id uuid NOT NULL REFERENCES courses, code text NOT NULL, UNIQUE(term_id,code));
CREATE TABLE teaching_assignments(section_id uuid REFERENCES class_sections, lecturer_id uuid REFERENCES lecturers, PRIMARY KEY(section_id,lecturer_id));
CREATE TABLE enrollments(section_id uuid REFERENCES class_sections, student_id uuid REFERENCES students, PRIMARY KEY(section_id,student_id));
CREATE TABLE schedules(id uuid PRIMARY KEY, section_id uuid NOT NULL REFERENCES class_sections, classroom_id uuid NOT NULL REFERENCES classrooms, starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL CHECK(ends_at>starts_at));
CREATE TABLE attendance_sessions(id uuid PRIMARY KEY, schedule_id uuid NOT NULL REFERENCES schedules, section_id uuid NOT NULL REFERENCES class_sections, classroom_id uuid NOT NULL REFERENCES classrooms, device_id uuid NOT NULL REFERENCES devices, opened_by uuid NOT NULL REFERENCES lecturers, status text NOT NULL CHECK(status IN('SCHEDULED','OPEN','CLOSED','CANCELLED')), late_after timestamptz NOT NULL, opened_at timestamptz, closed_at timestamptz, version integer NOT NULL DEFAULT 1);
CREATE UNIQUE INDEX open_session_device ON attendance_sessions(device_id) WHERE status='OPEN';
CREATE UNIQUE INDEX open_session_schedule ON attendance_sessions(schedule_id) WHERE status='OPEN';
CREATE TABLE attendance_session_devices(session_id uuid REFERENCES attendance_sessions, device_id uuid REFERENCES devices, PRIMARY KEY(session_id,device_id));
CREATE TABLE attendance_session_roster(session_id uuid REFERENCES attendance_sessions, student_id uuid REFERENCES students, PRIMARY KEY(session_id,student_id));
CREATE TABLE attendance_records(id uuid PRIMARY KEY, session_id uuid NOT NULL, student_id uuid NOT NULL, status text NOT NULL CHECK(status IN('PRESENT','LATE','ABSENT','EXCUSED')), source text NOT NULL CHECK(source IN('DEMO','MANUAL')), received_at timestamptz NOT NULL DEFAULT clock_timestamp(), version integer NOT NULL DEFAULT 1, UNIQUE(session_id,student_id), FOREIGN KEY(session_id,student_id) REFERENCES attendance_session_roster);
CREATE TABLE attendance_adjustment_requests(id uuid PRIMARY KEY, record_id uuid NOT NULL REFERENCES attendance_records, student_id uuid NOT NULL REFERENCES students, requested_status text NOT NULL CHECK(requested_status IN('PRESENT','LATE','EXCUSED')), reason text NOT NULL, status text NOT NULL CHECK(status IN('PENDING','APPROVED','REJECTED')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE attendance_corrections(id uuid PRIMARY KEY, record_id uuid NOT NULL REFERENCES attendance_records, old_status text NOT NULL, new_status text NOT NULL, reason text NOT NULL, actor_id uuid NOT NULL REFERENCES users, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE device_contexts(id uuid PRIMARY KEY, device_id uuid NOT NULL REFERENCES devices, purpose text NOT NULL CHECK(purpose IN('PARKING_ENTRY','PARKING_EXIT','CANTEEN','ENROLLMENT','ATTENDANCE')), order_id uuid REFERENCES orders, parking_session_id uuid REFERENCES parking_sessions, parking_lot_id uuid REFERENCES parking_lots, enrollment_student_id uuid REFERENCES students, attendance_session_id uuid REFERENCES attendance_sessions, config_version integer NOT NULL, status text NOT NULL DEFAULT 'OPEN' CHECK(status IN('OPEN','CONSUMED','CANCELLED')), expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), CHECK(num_nonnulls(order_id,parking_session_id,parking_lot_id,enrollment_student_id,attendance_session_id)=1));
CREATE UNIQUE INDEX one_context_device ON device_contexts(device_id) WHERE status='OPEN';
ALTER TABLE ocr_observations ADD FOREIGN KEY(context_id) REFERENCES device_contexts;
CREATE TABLE device_challenges(id uuid PRIMARY KEY, device_id uuid NOT NULL REFERENCES devices, context_id uuid NOT NULL REFERENCES device_contexts, nonce_hash text UNIQUE NOT NULL, config_version integer NOT NULL, expires_at timestamptz NOT NULL, consumed_at timestamptz);
CREATE TABLE device_events(id uuid PRIMARY KEY, device_id uuid NOT NULL REFERENCES devices, event_id uuid NOT NULL, context_id uuid NOT NULL REFERENCES device_contexts, payload_hash text NOT NULL, response jsonb NOT NULL, http_status integer NOT NULL, source text NOT NULL CHECK(source='REAL'), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(device_id,event_id));
CREATE TABLE simulation_events(id uuid PRIMARY KEY, actor_id uuid NOT NULL REFERENCES users, device_id uuid NOT NULL REFERENCES devices, context_id uuid REFERENCES device_contexts, scenario text NOT NULL, source text NOT NULL CHECK(source='DEMO'), result jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE identity_assertions(id uuid PRIMARY KEY, student_id uuid NOT NULL REFERENCES students, device_id uuid NOT NULL REFERENCES devices, context_id uuid NOT NULL REFERENCES device_contexts, source text NOT NULL CHECK(source IN('REAL','DEMO')), card_id uuid REFERENCES rfid_cards, credential_hmac text, expires_at timestamptz NOT NULL, consumed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE identity_assertions ADD COLUMN resource_id uuid;
ALTER TABLE payments ADD COLUMN identity_assertion_id uuid REFERENCES identity_assertions;
CREATE TABLE notifications(id uuid PRIMARY KEY, recipient_user_id uuid NOT NULL REFERENCES users, type text NOT NULL, message text NOT NULL, resource_id uuid, read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_logs(id uuid PRIMARY KEY, actor_id uuid REFERENCES users, device_id uuid REFERENCES devices, action text NOT NULL, resource_id uuid, reason text, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE idempotency_records(scope text NOT NULL, key text NOT NULL, payload_hash text NOT NULL, status integer NOT NULL, response jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(scope,key));
CREATE TABLE outbox_events(id uuid PRIMARY KEY, type text NOT NULL, aggregate_id uuid NOT NULL, recipient_user_id uuid REFERENCES users, payload jsonb NOT NULL, published_at timestamptz, attempts integer NOT NULL DEFAULT 0, lease_until timestamptz, dead_letter_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX outbox_pending ON outbox_events(created_at) WHERE published_at IS NULL;
CREATE TABLE rate_limit_counters(scope text NOT NULL, bucket bigint NOT NULL, count integer NOT NULL, PRIMARY KEY(scope,bucket));
CREATE TABLE system_settings(key text PRIMARY KEY,value jsonb NOT NULL,version integer NOT NULL DEFAULT 1,updated_at timestamptz NOT NULL DEFAULT now());

CREATE FUNCTION immutable_row() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'IMMUTABLE_RECORD'; END $$;
CREATE TRIGGER immutable_tx BEFORE UPDATE OR DELETE ON wallet_transactions FOR EACH ROW EXECUTE FUNCTION immutable_row();
CREATE TRIGGER immutable_entry BEFORE UPDATE OR DELETE ON wallet_ledger_entries FOR EACH ROW EXECUTE FUNCTION immutable_row();
CREATE TRIGGER immutable_audit BEFORE UPDATE OR DELETE ON audit_logs FOR EACH ROW EXECUTE FUNCTION immutable_row();
CREATE TRIGGER immutable_stock BEFORE UPDATE OR DELETE ON inventory_movements FOR EACH ROW EXECUTE FUNCTION immutable_row();
CREATE FUNCTION seal_entry() RETURNS trigger LANGUAGE plpgsql SET search_path=campus,pg_temp AS $$ BEGIN
 IF NOT EXISTS(SELECT 1 FROM wallet_transactions WHERE id=NEW.transaction_id AND creation_xid=pg_current_xact_id()) THEN RAISE EXCEPTION 'SEALED_TRANSACTION'; END IF; RETURN NEW; END $$;
CREATE TRIGGER seal_ledger BEFORE INSERT ON wallet_ledger_entries FOR EACH ROW EXECUTE FUNCTION seal_entry();
CREATE FUNCTION balanced_transaction() RETURNS trigger LANGUAGE plpgsql SET search_path=campus,pg_temp AS $$ DECLARE n integer; total numeric; BEGIN
 SELECT count(*),sum(delta_points) INTO n,total FROM wallet_ledger_entries WHERE transaction_id=NEW.id;
 IF n<2 OR total<>0 THEN RAISE EXCEPTION 'UNBALANCED_TRANSACTION'; END IF; RETURN NULL; END $$;
CREATE CONSTRAINT TRIGGER balanced_ledger AFTER INSERT ON wallet_transactions DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION balanced_transaction();

CREATE FUNCTION post_wallet(p_id uuid,p_type text,p_student uuid,p_amount bigint,p_payment uuid,p_topup uuid,p_original uuid,p_refund uuid,p_adjust uuid)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=campus,pg_temp AS $$
DECLARE student_account uuid; other_account uuid; other_kind text; direction integer; held bigint; available bigint; original wallet_transactions; p payments; t topup_orders; r refunds; a wallet_adjustments;
BEGIN
 IF p_amount<=0 THEN RAISE EXCEPTION 'INVALID_AMOUNT'; END IF;
 SELECT account_id INTO STRICT student_account FROM wallets WHERE student_id=p_student AND status='ACTIVE' FOR UPDATE;
 IF p_type='TOP_UP' THEN
   SELECT * INTO STRICT t FROM topup_orders WHERE id=p_topup FOR UPDATE;
   IF t.status<>'PENDING' OR t.amount_points<>p_amount OR NOT EXISTS(SELECT 1 FROM wallets WHERE id=t.wallet_id AND student_id=p_student) THEN RAISE EXCEPTION 'INVALID_TOPUP'; END IF;
   other_kind:='MOCK_SOURCE'; direction:=1;
 ELSIF p_type IN('CANTEEN_PAYMENT','PARKING_PAYMENT') THEN
   SELECT * INTO STRICT p FROM payments WHERE id=p_payment FOR UPDATE;
   IF p.student_id<>p_student OR p.amount_points<>p_amount OR p.status NOT IN('AWAITING_CONFIRMATION','AUTHORIZED') OR (p_type='CANTEEN_PAYMENT')<>(p.order_id IS NOT NULL) THEN RAISE EXCEPTION 'INVALID_PAYMENT'; END IF;
   other_kind:=CASE WHEN p_type='CANTEEN_PAYMENT' THEN 'CANTEEN' ELSE 'PARKING' END; direction:=-1;
 ELSIF p_type IN('REFUND','REVERSAL') THEN
   SELECT * INTO STRICT original FROM wallet_transactions WHERE id=p_original FOR UPDATE;
   SELECT * INTO STRICT r FROM refunds WHERE id=p_refund;
   IF original.student_id<>p_student OR original.type NOT IN('CANTEEN_PAYMENT','PARKING_PAYMENT') OR r.original_transaction_id<>p_original OR r.amount_points<>p_amount THEN RAISE EXCEPTION 'INVALID_REFUND'; END IF;
   IF coalesce((SELECT sum(amount_points) FROM wallet_transactions WHERE original_transaction_id=p_original),0)+p_amount>original.amount_points THEN RAISE EXCEPTION 'REFUND_EXCEEDS_ORIGINAL'; END IF;
   other_kind:=CASE WHEN original.type='CANTEEN_PAYMENT' THEN 'CANTEEN' ELSE 'PARKING' END; direction:=1;
 ELSE
   SELECT * INTO STRICT a FROM wallet_adjustments WHERE id=p_adjust;
   IF p_type<>'ADMIN_ADJUSTMENT' OR a.student_id<>p_student OR abs(a.delta_points)<>p_amount THEN RAISE EXCEPTION 'INVALID_ADJUSTMENT'; END IF;
   direction:=CASE WHEN a.delta_points>0 THEN 1 ELSE -1 END; other_kind:='ADJUSTMENT';
 END IF;
 SELECT id INTO STRICT other_account FROM ledger_accounts WHERE kind=other_kind;
 PERFORM id FROM ledger_accounts WHERE id IN(student_account,other_account) ORDER BY id FOR UPDATE;
 SELECT coalesce(sum(h.amount_points),0) INTO held FROM wallet_holds h JOIN wallets w ON w.id=h.wallet_id WHERE w.student_id=p_student AND h.status='ACTIVE';
 SELECT balance_points-held INTO available FROM ledger_accounts WHERE id=student_account;
 IF direction=-1 AND available<p_amount THEN RAISE EXCEPTION 'INSUFFICIENT_POINTS'; END IF;
 INSERT INTO wallet_transactions(id,type,student_id,amount_points,payment_id,topup_order_id,original_transaction_id,refund_id,adjustment_id) VALUES(p_id,p_type,p_student,p_amount,p_payment,p_topup,p_original,p_refund,p_adjust);
 INSERT INTO wallet_ledger_entries(id,transaction_id,account_id,delta_points) VALUES(gen_random_uuid(),p_id,student_account,direction*p_amount),(gen_random_uuid(),p_id,other_account,-direction*p_amount);
 UPDATE ledger_accounts SET balance_points=balance_points+direction*p_amount WHERE id=student_account;
 UPDATE ledger_accounts SET balance_points=balance_points-direction*p_amount WHERE id=other_account;
 RETURN p_id;
END $$;
REVOKE ALL ON FUNCTION post_wallet(uuid,text,uuid,bigint,uuid,uuid,uuid,uuid,uuid) FROM PUBLIC;
